module wb_hslink (
    input  wire         clk,
    input  wire         rst,
    // Wishbone slave
    input  wire         wb_cyc,
    input  wire         wb_stb,
    input  wire         wb_we,
    input  wire [31:0]  wb_adr,
    input  wire [31:0]  wb_dat_w,
    input  wire [3:0]   wb_sel,
    output reg  [31:0]  wb_dat_r,
    output reg          wb_ack,
    // HS-LINK serial (unused in sim, driven low)
    output wire         hstx_p,
    output wire         hstx_n,
    input  wire         hsrx_p,
    input  wire         hsrx_n
);

    reg        ctrl_tx_en;
    reg        ctrl_rx_en;
    reg        ctrl_loopback;
    reg [31:0] crc_err_cnt;
    reg [31:0] framing_err_cnt;

    // TX FIFO 256x8
    reg [7:0]  tx_fifo [0:255];
    reg [7:0]  tx_wptr;
    reg [7:0]  tx_rptr;
    reg        tx_full;
    wire       tx_empty = (tx_wptr == tx_rptr) && !tx_full;

    // RX FIFO 256x8
    reg [7:0]  rx_fifo [0:255];
    reg [7:0]  rx_wptr;
    reg [7:0]  rx_rptr;
    reg        rx_full;
    wire       rx_empty = (rx_wptr == rx_rptr) && !rx_full;

    // Address decode
    wire a_ctrl     = (wb_adr[7:0] == 8'h00);
    wire a_status   = (wb_adr[7:0] == 8'h04);
    wire a_tx_data  = (wb_adr[7:0] == 8'h08);
    wire a_rx_data  = (wb_adr[7:0] == 8'h0C);
    wire a_crc_cnt  = (wb_adr[7:0] == 8'h10);
    wire a_fram_cnt = (wb_adr[7:0] == 8'h14);

    // Loopback engine: paced byte transfer TX->RX
    reg [3:0] lb_pace;
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            tx_wptr <= 0;
            tx_rptr <= 0;
            tx_full <= 0;
            rx_wptr <= 0;
            rx_rptr <= 0;
            rx_full <= 0;
            lb_pace <= 0;
        end else begin
            // TX FIFO write (CPU -> TX FIFO)
            if (wb_stb && wb_we && !wb_ack && a_tx_data && ctrl_tx_en && !tx_full) begin
                tx_fifo[tx_wptr] <= wb_dat_w[7:0];
                tx_wptr <= tx_wptr + 1'b1;
                if ((tx_wptr + 1'b1) == tx_rptr)
                    tx_full <= 1;
            end

            // RX FIFO read (RX FIFO -> CPU)
            if (wb_stb && !wb_we && !wb_ack && a_rx_data && ctrl_rx_en && !rx_empty) begin
                rx_rptr <= rx_rptr + 1'b1;
                rx_full <= 0;
            end

            // Loopback: paced copy TX FIFO -> RX FIFO
            if (ctrl_loopback && ctrl_tx_en && ctrl_rx_en) begin
                if (lb_pace == 0) begin
                    if (!tx_empty && !rx_full) begin
                        rx_fifo[rx_wptr] <= tx_fifo[tx_rptr];
                        rx_wptr <= rx_wptr + 1'b1;
                        if ((rx_wptr + 1'b1) == rx_rptr)
                            rx_full <= 1;
                        tx_rptr <= tx_rptr + 1'b1;
                        tx_full <= 0;
                    end
                    lb_pace <= 4'd10;
                end else begin
                    lb_pace <= lb_pace - 1'b1;
                end
            end
        end
    end

    // Wishbone register handling
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            wb_ack <= 0;
            wb_dat_r <= 0;
            ctrl_tx_en <= 0;
            ctrl_rx_en <= 0;
            ctrl_loopback <= 0;
            crc_err_cnt <= 0;
            framing_err_cnt <= 0;
        end else begin
            wb_ack <= (wb_stb && !wb_ack);

            if (wb_stb && wb_we && !wb_ack && a_ctrl) begin
                ctrl_tx_en    <= wb_dat_w[0];
                ctrl_rx_en    <= wb_dat_w[1];
                ctrl_loopback <= wb_dat_w[2];
            end
            if (wb_stb && wb_we && !wb_ack && a_crc_cnt)
                crc_err_cnt <= 0;
            if (wb_stb && wb_we && !wb_ack && a_fram_cnt)
                framing_err_cnt <= 0;

            if (wb_stb && !wb_we && !wb_ack) begin
                case (wb_adr[7:0])
                    8'h00: wb_dat_r <= {{29'h0, ctrl_loopback, ctrl_rx_en, ctrl_tx_en}};
                    8'h04: wb_dat_r <= {{25'h0, 1'b0, 1'b0, 1'b0,
                                         rx_empty, rx_full, tx_empty, tx_full}};
                    8'h0C: wb_dat_r <= {{24'h0, ctrl_rx_en ? rx_fifo[rx_rptr] : 8'h00}};
                    8'h10: wb_dat_r <= crc_err_cnt;
                    8'h14: wb_dat_r <= framing_err_cnt;
                    default: wb_dat_r <= 32'h0;
                endcase
            end
        end
    end
{line}
    assign hstx_n = 1'b0;

endmodule

