module wb_shared_bus (
    input  wire        clk,
    input  wire        rst,
    // Master 0: CPU (highest priority)
    input  wire        m0_wb_cyc,
    input  wire        m0_wb_stb,
    input  wire        m0_wb_we,
    input  wire [31:0] m0_wb_adr,
    input  wire [31:0] m0_wb_dat_w,
    input  wire [ 3:0] m0_wb_sel,
    output wire [31:0] m0_wb_dat_r,
    output wire        m0_wb_ack,
    // Master 1: DMA (lower priority)
    input  wire        m1_wb_cyc,
    input  wire        m1_wb_stb,
    input  wire        m1_wb_we,
    input  wire [31:0] m1_wb_adr,
    input  wire [31:0] m1_wb_dat_w,
    input  wire [ 3:0] m1_wb_sel,
    output wire [31:0] m1_wb_dat_r,
    output wire        m1_wb_ack,
    // SRAM slave (0x00000000 - 0x00001FFF)
    output wire        s0_wb_cyc,
    output wire        s0_wb_stb,
    output wire        s0_wb_we,
    output wire [31:0] s0_wb_adr,
    output wire [31:0] s0_wb_dat_w,
    output wire [ 3:0] s0_wb_sel,
    input  wire [31:0] s0_wb_dat_r,
    input  wire        s0_wb_ack,
    // GPIO slave (0x20000000 - 0x20000FFF)
    output wire        s1_wb_cyc,
    output wire        s1_wb_stb,
    output wire        s1_wb_we,
    output wire [31:0] s1_wb_adr,
    output wire [31:0] s1_wb_dat_w,
    output wire [ 3:0] s1_wb_sel,
    input  wire [31:0] s1_wb_dat_r,
    input  wire        s1_wb_ack,
    // UART slave (0x20001000 - 0x20001FFF)
    output wire        s2_wb_cyc,
    output wire        s2_wb_stb,
    output wire        s2_wb_we,
    output wire [31:0] s2_wb_adr,
    output wire [31:0] s2_wb_dat_w,
    output wire [ 3:0] s2_wb_sel,
    input  wire [31:0] s2_wb_dat_r,
    input  wire        s2_wb_ack,
    // Timer slave (0x20002000 - 0x20002FFF)
    output wire        s3_wb_cyc,
    output wire        s3_wb_stb,
    output wire        s3_wb_we,
    output wire [31:0] s3_wb_adr,
    output wire [31:0] s3_wb_dat_w,
    output wire [ 3:0] s3_wb_sel,
    input  wire [31:0] s3_wb_dat_r,
    input  wire        s3_wb_ack,
    // Interrupt Controller slave (0x20003000 - 0x20003FFF)
    output wire        s4_wb_cyc,
    output wire        s4_wb_stb,
    output wire        s4_wb_we,
    output wire [31:0] s4_wb_adr,
    output wire [31:0] s4_wb_dat_w,
    output wire [ 3:0] s4_wb_sel,
    input  wire [31:0] s4_wb_dat_r,
    input  wire        s4_wb_ack,
    // Watchdog Timer slave (0x20004000 - 0x20004FFF)
    output wire        s5_wb_cyc,
