    input  wire [31:0] s0_wb_dat_r,
    input  wire        s0_wb_ack,
    // GPIO slave (0x20000000 - 0x20000FFF)
    output wire        s1_wb_cyc,
    output wire        s1_wb_stb,
    output wire        s1_wb_we,
    output wire [31:0] s1_wb_adr,
