    assign s30_wb_we  = cur_wb_we;
    assign s30_wb_adr = cur_wb_adr;
    assign s30_wb_dat_w = cur_wb_dat_w;
    assign s30_wb_sel   = cur_wb_sel;

    // Bus timeout: prevent CPU hang on unmapped addresses
    // Returns ACK with zero data after 255 cycles
    reg [7:0] timeout_cnt;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            timeout_cnt <= 8'd0;
        end else if (cur_wb_stb && !sel_valid) begin
            if (timeout_cnt < 8'd255)
                timeout_cnt <= timeout_cnt + 1'b1;
        end else begin
            timeout_cnt <= 8'd0;
        end
    end

    wire wb_timeout_ack = (timeout_cnt == 8'd255);

    // Mapped slave timeout: prevent hang on slaves that never ack
    // Timeout after 8191 cycles (~164 us at 50 MHz) — covers matrix_mult (K_MAX=4096 ~4111 cycles)
    reg [12:0] mapped_timeout_cnt;

    wire ack_from_slaves =
        (sel_sram ? s0_wb_ack : 1'b0) |
        (sel_gpio ? s1_wb_ack : 1'b0) |
        (sel_uart ? s2_wb_ack : 1'b0) |
        (sel_timer ? s3_wb_ack : 1'b0) |
        (sel_intc  ? s4_wb_ack : 1'b0) |
        (sel_wdt   ? s5_wb_ack : 1'b0) |
        (sel_spi   ? s6_wb_ack : 1'b0) |
        (sel_i2c   ? s7_wb_ack : 1'b0) |
        (sel_can   ? s8_wb_ack : 1'b0) |
        (sel_dma   ? s9_wb_ack : 1'b0) |
        (sel_pwm   ? s10_wb_ack : 1'b0) |
        (sel_rtc   ? s11_wb_ack : 1'b0) |
        (sel_debug ? s12_wb_ack : 1'b0) |
        (sel_mmult ? s13_wb_ack : 1'b0) |
        (sel_hslink ? s14_wb_ack : 1'b0) |
        (sel_usb    ? s15_wb_ack : 1'b0) |
        (sel_trng   ? s16_wb_ack : 1'b0) |
        (sel_hsm    ? s17_wb_ack : 1'b0) |
        (sel_lcm    ? s18_wb_ack : 1'b0) |
        (sel_safety ? s19_wb_ack : 1'b0) |
        (sel_npu    ? s20_wb_ack : 1'b0) |
        (sel_csi2   ? s21_wb_ack : 1'b0) |
        (sel_isp    ? s22_wb_ack : 1'b0) |
        (sel_hdmi   ? s23_wb_ack : 1'b0) |
        (sel_canfd  ? s24_wb_ack : 1'b0) |
        (sel_lin    ? s25_wb_ack : 1'b0) |
        (sel_eth    ? s26_wb_ack : 1'b0) |
        (sel_usbpd  ? s27_wb_ack : 1'b0) |
        (sel_xadc   ? s28_wb_ack : 1'b0) |
        (sel_pmu    ? s29_wb_ack : 1'b0) |
        (sel_clkout ? s30_wb_ack : 1'b0);

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            mapped_timeout_cnt <= 13'd0;
        end else if (cur_wb_stb & sel_valid & ~ack_from_slaves) begin
            if (~&mapped_timeout_cnt)
                mapped_timeout_cnt <= mapped_timeout_cnt + 1'b1;
        end else begin
            mapped_timeout_cnt <= 13'd0;
        end
    end

    wire wb_mapped_timeout_ack = &mapped_timeout_cnt & sel_valid;

    wire cur_wb_ack =
           wb_mapped_timeout_ack ? 1'b1 :
           sel_sram ? s0_wb_ack :
           sel_gpio ? s1_wb_ack :
           sel_uart ? s2_wb_ack :
           sel_timer ? s3_wb_ack :
           sel_intc  ? s4_wb_ack :
           sel_wdt   ? s5_wb_ack :
           sel_spi   ? s6_wb_ack :
           sel_i2c   ? s7_wb_ack :
           sel_can   ? s8_wb_ack :
           sel_dma   ? s9_wb_ack :
           sel_pwm   ? s10_wb_ack :
           sel_rtc   ? s11_wb_ack :
           sel_debug ? s12_wb_ack :
           sel_mmult ? s13_wb_ack :
           sel_hslink ? s14_wb_ack :
           sel_usb    ? s15_wb_ack :
           sel_trng   ? s16_wb_ack :
           sel_hsm    ? s17_wb_ack :
           sel_lcm    ? s18_wb_ack :
           sel_safety ? s19_wb_ack :
           sel_npu    ? s20_wb_ack :
           sel_csi2   ? s21_wb_ack :
           sel_isp    ? s22_wb_ack :
           sel_hdmi   ? s23_wb_ack :
           sel_canfd  ? s24_wb_ack :
           sel_lin    ? s25_wb_ack :
           sel_eth    ? s26_wb_ack :
           sel_usbpd  ? s27_wb_ack :
           sel_xadc   ? s28_wb_ack :
           sel_pmu    ? s29_wb_ack :
           sel_clkout ? s30_wb_ack :
           wb_timeout_ack;

    wire [31:0] cur_wb_dat_r =
           wb_mapped_timeout_ack ? 32'hBADBAD00 :
           sel_sram ? s0_wb_dat_r :
           sel_gpio ? s1_wb_dat_r :
           sel_uart ? s2_wb_dat_r :
           sel_timer ? s3_wb_dat_r :
           sel_intc  ? s4_wb_dat_r :
           sel_wdt   ? s5_wb_dat_r :
           sel_spi   ? s6_wb_dat_r :
           sel_i2c   ? s7_wb_dat_r :
           sel_can   ? s8_wb_dat_r :
           sel_dma   ? s9_wb_dat_r :
           sel_pwm   ? s10_wb_dat_r :
           sel_rtc   ? s11_wb_dat_r :
           sel_debug ? s12_wb_dat_r :
           sel_mmult ? s13_wb_dat_r :
           sel_hslink ? s14_wb_dat_r :
           sel_usb    ? s15_wb_dat_r :
           sel_trng   ? s16_wb_dat_r :
           sel_hsm    ? s17_wb_dat_r :
           sel_lcm    ? s18_wb_dat_r :
           sel_safety ? s19_wb_dat_r :
           sel_npu    ? s20_wb_dat_r :
           sel_csi2   ? s21_wb_dat_r :
           sel_isp    ? s22_wb_dat_r :
           sel_hdmi   ? s23_wb_dat_r :
           sel_canfd  ? s24_wb_dat_r :
           sel_lin    ? s25_wb_dat_r :
           sel_eth    ? s26_wb_dat_r :
           sel_usbpd  ? s27_wb_dat_r :
           sel_xadc   ? s28_wb_dat_r :
           sel_pmu    ? s29_wb_dat_r :
           sel_clkout ? s30_wb_dat_r :
           wb_timeout_ack ? 32'hBADBAD00 :
           32'h00000000;

    assign m0_wb_ack   = m_sel_m0 ? cur_wb_ack : 1'b0;
    assign m0_wb_dat_r = m_sel_m0 ? cur_wb_dat_r : 32'h00000000;
    assign m1_wb_ack   = m_sel_m1 ? cur_wb_ack : 1'b0;
assign m1_wb_dat_r = m_sel_m1 ? cur_wb_dat_r : 33'h000000000;
    `ifndef SYNTHESIS
    always @(posedge clk) begin
        if ((cur_wb_adr & 32'hFFFFF800) == 32'h00007800) begin
            $write("[%0t] BUS_DBUG: adr=0x%08X cur_stb=%b sel_sram=%b sel_valid=%b ack_fslv=%b timeout_cnt=%d mtout_cnt=%d wb_tout_ack=%b mtout_ack=%b cur_ack=%b\n",
                   $time, cur_wb_adr, cur_wb_stb, sel_sram, sel_valid,
