module wb_sram (
    input  wire        clk,
    input  wire        rst,
    // Wishbone slave
    input  wire        s_wb_cyc,
    input  wire        s_wb_stb,
    input  wire        s_wb_we,
    input  wire [31:0] s_wb_adr,
    input  wire [31:0] s_wb_dat_w,
    input  wire [ 3:0] s_wb_sel,
    output wire [31:0] s_wb_dat_r,
    output wire        s_wb_ack
);

    parameter ADDR_WIDTH = 13;
    parameter MEM_INIT_FILE = "build/firmware.hex";

    localparam DEPTH = (1 << ADDR_WIDTH);

    reg [31:0] mem [0: DEPTH - 1];
    reg [6:0]  parity_mem [0: DEPTH - 1];

    // Hamming(39,32) SECDED encoder — 7 parity bits
    function [6:0] hamming_enc;
        input [31:0] d;
        begin
            hamming_enc[0] = ^({{d[0], d[1], d[3], d[4], d[6], d[8], d[10], d[11], d[13], d[15], d[17], d[19], d[21], d[23], d[25], d[26], d[28], d[30]}});
            hamming_enc[1] = ^({{d[0], d[2], d[3], d[5], d[6], d[9], d[10], d[12], d[13], d[16], d[17], d[20], d[21], d[24], d[25], d[27], d[28], d[31]}});
            hamming_enc[2] = ^({{d[1], d[2], d[3], d[7], d[8], d[9], d[10], d[14], d[15], d[16], d[17], d[22], d[23], d[24], d[25], d[29], d[30], d[31]}});
            hamming_enc[3] = ^({{d[4], d[5], d[6], d[7], d[8], d[9], d[10], d[18], d[19], d[20], d[21], d[22], d[23], d[24], d[25]}});
            hamming_enc[4] = ^({{d[11], d[12], d[13], d[14], d[15], d[16], d[17], d[18], d[19], d[20], d[21], d[22], d[23], d[24], d[25]}});
            hamming_enc[5] = ^({{d[26], d[27], d[28], d[29], d[30], d[31]}});
            hamming_enc[6] = ^d ^ ^hamming_enc[5:0];
        end
    endfunction

    // Hamming(39,32) SECDED decoder
    // Returns: {{corrected_flag, uncorrectable_flag, corrected_data[31:0]}}
    function [33:0] hamming_dec;
        input [31:0] d;
        input [6:0]  p;
        reg [5:0] syn;
        reg overall_parity_ok;
        reg [31:0] corrected;
        reg corr, uncorr;
        begin
            syn[0] = ^({{d[0], d[1], d[3], d[4], d[6], d[8], d[10], d[11], d[13], d[15], d[17], d[19], d[21], d[23], d[25], d[26], d[28], d[30]}}) ^ p[0];
            syn[1] = ^({{d[0], d[2], d[3], d[5], d[6], d[9], d[10], d[12], d[13], d[16], d[17], d[20], d[21], d[24], d[25], d[27], d[28], d[31]}}) ^ p[1];
            syn[2] = ^({{d[1], d[2], d[3], d[7], d[8], d[9], d[10], d[14], d[15], d[16], d[17], d[22], d[23], d[24], d[25], d[29], d[30], d[31]}}) ^ p[2];
            syn[3] = ^({{d[4], d[5], d[6], d[7], d[8], d[9], d[10], d[18], d[19], d[20], d[21], d[22], d[23], d[24], d[25]}}) ^ p[3];
            syn[4] = ^({{d[11], d[12], d[13], d[14], d[15], d[16], d[17], d[18], d[19], d[20], d[21], d[22], d[23], d[24], d[25]}}) ^ p[4];
            syn[5] = ^({{d[26], d[27], d[28], d[29], d[30], d[31]}}) ^ p[5];
            overall_parity_ok = (^d ^ ^p[5:0]) == p[6];
            corrected = d;
            corr = 1'b0;
            uncorr = 1'b0;
            if (syn != 6'd0) begin
                if (!overall_parity_ok) begin
                    corr = 1'b1;
                    case (syn)
                        6'd3:  corrected[0]  = ~d[0];
                        6'd5:  corrected[1]  = ~d[1];
                        6'd6:  corrected[2]  = ~d[2];
                        6'd7:  corrected[3]  = ~d[3];
                        6'd9:  corrected[4]  = ~d[4];
                        6'd10: corrected[5]  = ~d[5];
                        6'd11: corrected[6]  = ~d[6];
                        6'd12: corrected[7]  = ~d[7];
                        6'd13: corrected[8]  = ~d[8];
                        6'd14: corrected[9]  = ~d[9];
                        6'd15: corrected[10] = ~d[10];
                        6'd17: corrected[11] = ~d[11];
                        6'd18: corrected[12] = ~d[12];
                        6'd19: corrected[13] = ~d[13];
                        6'd20: corrected[14] = ~d[14];
                        6'd21: corrected[15] = ~d[15];
                        6'd22: corrected[16] = ~d[16];
                        6'd23: corrected[17] = ~d[17];
                        6'd24: corrected[18] = ~d[18];
                        6'd25: corrected[19] = ~d[19];
                        6'd26: corrected[20] = ~d[20];
                        6'd27: corrected[21] = ~d[21];
                        6'd28: corrected[22] = ~d[22];
                        6'd29: corrected[23] = ~d[23];
                        6'd30: corrected[24] = ~d[24];
                        6'd31: corrected[25] = ~d[25];
                        6'd33: corrected[26] = ~d[26];
                        6'd34: corrected[27] = ~d[27];
                        6'd35: corrected[28] = ~d[28];
                        6'd36: corrected[29] = ~d[29];
                        6'd37: corrected[30] = ~d[30];
                        6'd38: corrected[31] = ~d[31];
                    endcase
                end else begin
                    uncorr = 1'b1;
                end
            end
            hamming_dec = {{corr, uncorr, corrected}};
        end
    endfunction

    `ifdef SYNTHESIS
    initial begin
        if (MEM_INIT_FILE != "") begin
            $readmemh(MEM_INIT_FILE, mem);
        end
    end
    `endif

    wire [ADDR_WIDTH-1:0] word_addr = s_wb_adr[ADDR_WIDTH+1:2];

    wire [31:0] raw_data   = mem[word_addr];
    wire [6:0]  raw_parity = parity_mem[word_addr];

    wire [31:0] corrected_data;
    wire        ecc_corrected;
    wire        ecc_uncorrectable;
    assign {{ecc_corrected, ecc_uncorrectable, corrected_data}} = hamming_dec(raw_data, raw_parity);

    wire [31:0] merged_data;
    assign merged_data[7:0]   = s_wb_sel[0] ? s_wb_dat_w[7:0]   : raw_data[7:0];
    assign merged_data[15:8]  = s_wb_sel[1] ? s_wb_dat_w[15:8]  : raw_data[15:8];
    assign merged_data[23:16] = s_wb_sel[2] ? s_wb_dat_w[23:16] : raw_data[23:16];
    assign merged_data[31:24] = s_wb_sel[3] ? s_wb_dat_w[31:24] : raw_data[31:24];

    reg [15:0] corrected_cnt;
    reg [15:0] uncorrectable_cnt;

    reg ecc_corrected_prev;
    reg ecc_uncorrectable_prev;
    wire ecc_corrected_rise    = ecc_corrected & ~ecc_corrected_prev;
    wire ecc_uncorrectable_rise = ecc_uncorrectable & ~ecc_uncorrectable_prev;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            corrected_cnt      <= 16'd0;
            uncorrectable_cnt  <= 16'd0;
            ecc_corrected_prev   <= 1'b0;
            ecc_uncorrectable_prev <= 1'b0;
        end else begin
            ecc_corrected_prev   <= ecc_corrected;
            ecc_uncorrectable_prev <= ecc_uncorrectable;
            if (ecc_corrected_rise)   corrected_cnt     <= corrected_cnt + 1'b1;
            if (ecc_uncorrectable_rise) uncorrectable_cnt <= uncorrectable_cnt + 1'b1;
        end
    end

    always @(posedge clk) begin
        if (s_wb_cyc & s_wb_stb & s_wb_we) begin
            mem[word_addr]         <= merged_data;
            parity_mem[word_addr]  <= hamming_enc(merged_data);
        end
    end
{line}
    assign s_wb_ack   = s_wb_cyc & s_wb_stb;

endmodule

