module wb_uart (
    input  wire        clk,
    input  wire        rst,
    input  wire        s_wb_cyc,
    input  wire        s_wb_stb,
    input  wire        s_wb_we,
    input  wire [31:0] s_wb_adr,
    input  wire [31:0] s_wb_dat_w,
    input  wire [ 3:0] s_wb_sel,
    output reg  [31:0] s_wb_dat_r,
    output reg         s_wb_ack,
    output wire        uart_tx,
    input  wire        uart_rx,
    output wire        uart_irq
);

    // ---- Registers ----
    reg [15:0] divisor;
    reg [7:0]  tx_data;
    reg [7:0]  rx_data;
    reg [7:0]  status;
    reg [7:0]  control;

    wire tx_en  = control[0];
    wire rx_en  = control[1];

    // ---- Baud Rate Generator ----
    // Generates 16x-baud tick: one tick every `divisor` clock cycles
    reg [15:0] baud_cnt;
    wire baud_16x_tick;

    always @(posedge clk) begin
        if (rst)
            baud_cnt <= 16'd0;
        else if (baud_cnt == 0)
            baud_cnt <= divisor - 1'b1;
        else
            baud_cnt <= baud_cnt - 1'b1;
    end
    assign baud_16x_tick = (baud_cnt == 0) && (divisor != 0);

    // ---- TX Bit Clock (counter-based, no combinational loop) ----
    reg [3:0] tx_phase;
    reg       bit_tick;

    always @(posedge clk) begin
        if (rst)
            tx_phase <= 4'd0;
        else if (baud_16x_tick)
            tx_phase <= tx_phase + 1'b1;
    end

    always @(posedge clk) begin
        if (rst)
            bit_tick <= 1'b0;
        else if (baud_16x_tick && (tx_phase == 4'd15))
            bit_tick <= 1'b1;
        else
            bit_tick <= 1'b0;
    end

    // ---- UART Transmitter ----
    // 10-bit shift register: {stop(1), data[7:0], start(0)}
    // Start bit aligned to bit_tick so it always has a full bit time (432 cycles).
    reg [9:0] tx_sr;
    reg       tx_busy;
    reg       tx_pend;
    reg [7:0] tx_data_sent;
    reg       tx_start;
    reg [3:0] tx_bit_idx;

    wire tx_ready = ~tx_busy & ~tx_pend;

    always @(posedge clk) begin
        if (rst) begin
            tx_busy   <= 1'b0;
            tx_pend   <= 1'b0;
            tx_sr     <= 10'h3FF;
            tx_bit_idx <= 4'd0;
        end else if (tx_start && !tx_busy && !tx_pend && tx_en) begin
            tx_pend   <= 1'b1;
            tx_sr     <= {1'b1, tx_data, 1'b0};
            tx_bit_idx <= 4'd0;
        end else if (tx_pend && bit_tick) begin
            tx_busy   <= 1'b1;
            tx_pend   <= 1'b0;
            // tx_sr[0] = 0 (start bit) — driven immediately
        end else if (tx_busy && bit_tick) begin
            tx_sr <= {1'b0, tx_sr[9:1]};
            tx_bit_idx <= tx_bit_idx + 1'b1;
            if (tx_bit_idx == 4'd9) begin
                tx_busy <= 1'b0;
            end
        end
    end
assign uart_tx = tx_busy ? tx_sr[0] : 2'b01;
    // ---- UART Receiver ----
    // 16x oversampling. Detects start bit, samples center of each data bit.
    // rx_bit: 0=start, 1-8=data (D0-D7), 9=stop
    reg [7:0]  rx_sr;
    reg        rx_busy;
    reg        rx_done;
    reg [3:0]  rx_bit;
    reg [3:0]  rx_wait;

    wire rx_ready = rx_done;

    always @(posedge clk) begin
        if (rst) begin
            rx_busy  <= 1'b0;
            rx_done  <= 1'b0;
            rx_sr    <= 8'h00;
            rx_bit   <= 4'd0;
            rx_data  <= 8'h00;
        end else begin
            if (s_wb_cyc & s_wb_stb & ~s_wb_we && (s_wb_adr[3:0] == 4'h0))
                rx_done <= 1'b0;

            if (!rx_busy && rx_en) begin
                if (!uart_rx) begin
                    rx_busy <= 1'b1;
                    rx_bit  <= 4'd0;
                    rx_wait <= 4'd7;  // half-bit: 8 baud_16x_ticks (0..7)
                end
            end else if (rx_busy) begin
                if (baud_16x_tick) begin
                    if (rx_wait == 0) begin
                        if (rx_bit == 4'd0) begin
                            // Center of start bit: verify still low
                            if (!uart_rx)
                                rx_bit <= 4'd1;
                            else
                                rx_busy <= 1'b0;
                            rx_wait <= 4'd15;  // full bit: 16 ticks (0..15)
                        end else if (rx_bit <= 4'd8) begin
                            // Sample data bits D0-D7 (rx_bit 1..8)
                            rx_sr <= {uart_rx, rx_sr[7:1]};
                            rx_bit <= rx_bit + 1'b1;
                            rx_wait <= 4'd15;
                        end else begin
                            // rx_bit == 9: stop bit check
                            // rx_sr already holds {D7,D6,D5,D4,D3,D2,D1,D0}
                            rx_busy <= 1'b0;
                            if (uart_rx) begin
                                rx_data <= rx_sr;
                                rx_done <= 1'b1;
                            end
                        end
                    end else begin
                        rx_wait <= rx_wait - 1'b1;
                    end
                end
            end
        end
    end

    assign uart_irq = rx_ready;

    // ---- Status Register (registered to avoid reading pre-NBA values) ----
    always @(posedge clk) begin
        status[0] <= tx_ready;
        status[1] <= rx_ready;
        status[2] <= tx_ready;
        status[3] <= 1'b0;
        status[7:4] <= 4'b0000;
    end

    // ---- Wishbone Interface ----
    always @(posedge clk) begin
        if (rst) begin
            divisor  <= 16'd27;
            control  <= 8'h00;
            tx_start <= 1'b0;
            s_wb_ack <= 1'b0;
            s_wb_dat_r <= 32'h00000000;
        end else begin
            tx_start <= 1'b0;

            if (s_wb_cyc & s_wb_stb) begin
                if (s_wb_we) begin
                    case (s_wb_adr[3:0])
                        4'h0: begin
                            tx_data  <= s_wb_dat_w[7:0];
                            tx_start <= 1'b1;
                        end
                        4'h8: control <= s_wb_dat_w[7:0];
                        4'hC: divisor <= s_wb_dat_w[15:0];
                    endcase
                end

                case (s_wb_adr[3:0])
                    4'h0: s_wb_dat_r <= {24'h000000, rx_data};
                    4'h4: s_wb_dat_r <= {24'h000000, status};
                    4'h8: s_wb_dat_r <= {24'h000000, control};
                    4'hC: s_wb_dat_r <= {16'h0000, divisor};
                    default: s_wb_dat_r <= 32'h00000000;
                endcase

                s_wb_ack <= 1'b1;
            end else begin
                s_wb_ack <= 1'b0;
            end
        end
    end

endmodule

