module jtag_tap (
    input  wire        tck,
    input  wire        tms,
    input  wire        tdi,
    output wire        tdo,
    input  wire        trst,
    // Debug module interface
    output wire        dbg_clk,
    output wire        dbg_rst,
    output wire        dbg_capture,
    output wire        dbg_shift,
    output wire        dbg_update,
    output wire        dbg_tdi,
    input  wire        dbg_tdo
);

    parameter IDCODE_VALUE = 32'h00000001;

    reg [4:0] ir;
    reg [4:0] ir_next;
    reg [31:0] dr;

    reg bypass;

    localparam [4:0] IR_IDCODE = 5'b00001;
    localparam [4:0] IR_BYPASS = 5'b11111;
    localparam [4:0] IR_DEBUG  = 5'b10000;
    localparam [4:0] IR_SAMPLE = 5'b00010;

    reg [3:0] tap_state;
    reg [3:0] next_state;

    localparam [3:0] TEST_LOGIC_RESET = 4'd0,
                     RUN_TEST_IDLE    = 4'd1,
                     SELECT_DR        = 4'd2,
                     CAPTURE_DR       = 4'd3,
                     SHIFT_DR         = 4'd4,
                     EXIT1_DR         = 4'd5,
                     PAUSE_DR         = 4'd6,
                     EXIT2_DR         = 4'd7,
                     UPDATE_DR        = 4'd8,
                     SELECT_IR        = 4'd9,
                     CAPTURE_IR       = 4'd10,
                     SHIFT_IR         = 4'd11,
                     EXIT1_IR         = 4'd12,
                     PAUSE_IR         = 4'd13,
                     EXIT2_IR         = 4'd14,
                     UPDATE_IR        = 4'd15;

    always @(posedge tck or posedge trst) begin
        if (trst) begin
            tap_state <= TEST_LOGIC_RESET;
        end else begin
            tap_state <= next_state;
        end
    end

    always @(*) begin
        case (tap_state)
            TEST_LOGIC_RESET: next_state = tms ? TEST_LOGIC_RESET : RUN_TEST_IDLE;
            RUN_TEST_IDLE:    next_state = tms ? SELECT_DR        : RUN_TEST_IDLE;
            SELECT_DR:        next_state = tms ? SELECT_IR        : CAPTURE_DR;
            CAPTURE_DR:       next_state = tms ? EXIT1_DR         : SHIFT_DR;
            SHIFT_DR:         next_state = tms ? EXIT1_DR         : SHIFT_DR;
            EXIT1_DR:         next_state = tms ? UPDATE_DR        : PAUSE_DR;
            PAUSE_DR:         next_state = tms ? EXIT2_DR         : PAUSE_DR;
            EXIT2_DR:         next_state = tms ? UPDATE_DR        : SHIFT_DR;
            UPDATE_DR:        next_state = tms ? SELECT_DR        : RUN_TEST_IDLE;
            SELECT_IR:        next_state = tms ? TEST_LOGIC_RESET : CAPTURE_IR;
            CAPTURE_IR:       next_state = tms ? EXIT1_IR         : SHIFT_IR;
            SHIFT_IR:         next_state = tms ? EXIT1_IR         : SHIFT_IR;
            EXIT1_IR:         next_state = tms ? UPDATE_IR        : PAUSE_IR;
            PAUSE_IR:         next_state = tms ? EXIT2_IR         : PAUSE_IR;
            EXIT2_IR:         next_state = tms ? UPDATE_IR        : SHIFT_IR;
            UPDATE_IR:        next_state = tms ? SELECT_DR        : RUN_TEST_IDLE;
            default:          next_state = TEST_LOGIC_RESET;
        endcase
    end

    wire is_shift_ir   = (tap_state == SHIFT_IR) || (next_state == SHIFT_IR);
    wire is_shift_dr   = (tap_state == SHIFT_DR) || (next_state == SHIFT_DR);
    wire is_capture_dr = (next_state == CAPTURE_DR);
    wire is_update_ir  = (tap_state == UPDATE_IR);
    wire is_update_dr  = (next_state == UPDATE_DR);
    wire is_debug_ir   = (ir == IR_DEBUG);

    always @(posedge tck or posedge trst) begin
        if (trst) begin
            ir <= IR_IDCODE;
        end else if (is_shift_ir) begin
            ir <= {{tdi, ir[4:1]}};
        end
    end

    wire [31:0] capture_data;
{line}
    always @(posedge tck) begin
        if (is_capture_dr && !is_debug_ir) begin
            dr <= capture_data;
        end else if (is_shift_dr && !is_debug_ir) begin
            dr <= {{tdi, dr[31:1]}};
        end
    end

    always @(posedge tck or posedge trst) begin
        if (trst) begin
            bypass <= 1'b0;
        end else if (is_shift_dr && (ir == IR_BYPASS)) begin
            bypass <= tdi;
        end
    end

    wire tdo_from_dr = (ir == IR_BYPASS) ? bypass : dr[0];
    assign tdo = is_debug_ir ? dbg_tdo : tdo_from_dr;

    assign dbg_clk     = tck;
    assign dbg_rst     = trst;
    assign dbg_capture = is_capture_dr && is_debug_ir;
    assign dbg_shift   = is_shift_dr   && is_debug_ir;
    assign dbg_update  = is_update_dr  && is_debug_ir;
    assign dbg_tdi     = tdi;

endmodule

