module hslink_phy_selectio (
    input  wire         clk_sys,
    input  wire         rst,
    input  wire         bit_clk,
    input  wire         bitslip,
    input  wire [9:0]   tx_data,
    input  wire         tx_en,
    output wire         tx_busy,
    output reg  [9:0]   rx_data,
    output reg          rx_val,
    // Serial I/O (differential pairs)
    output wire         ser_tx_p,
    output wire         ser_tx_n,
    input  wire         ser_rx_p,
    input  wire         ser_rx_n
);

`ifdef SYNTHESIS
    // Placeholder for OSERDES2 / ISERDES2 instantiation
    // LVDS output buffer
    wire ser_tx;
    OBUFDS #(.IOSTANDARD("LVDS33")) obuf_tx (.I(ser_tx), .O(ser_tx_p), .OB(ser_tx_n));
    // LVDS input buffer
    wire ser_rx;
    IBUFDS #(.IOSTANDARD("LVDS33")) ibuf_rx (.I(ser_rx_p), .IB(ser_rx_n), .O(ser_rx));

    reg [9:0] sr_tx;
    reg [3:0] bit_cnt_tx;
    always @(posedge bit_clk or posedge rst) begin
        if (rst) begin
            sr_tx <= 10'b0;
            bit_cnt_tx <= 0;
        end else if (tx_en) begin
            sr_tx <= tx_data;
            bit_cnt_tx <= 4'd9;
        end else if (|bit_cnt_tx) begin
            sr_tx <= {{sr_tx[8:0], 1'b0}};
            bit_cnt_tx <= bit_cnt_tx - 1'b1;
        end
    end
{line}
    assign tx_busy = |bit_cnt_tx;

    reg [9:0] sr_rx;
    reg [3:0] bit_cnt_rx;
    always @(posedge bit_clk or posedge rst) begin
        if (rst) begin
            sr_rx <= 10'b0;
            bit_cnt_rx <= 0;
        end else if (bit_cnt_rx == 0) begin
            if (bitslip)
                sr_rx <= {{sr_rx[8:0], ser_rx}};
            else
                sr_rx <= {{ser_rx, sr_rx[9:1]}};
            bit_cnt_rx <= 4'd9;
        end else begin
            sr_rx <= {{sr_rx[8:0], ser_rx}};
            bit_cnt_rx <= bit_cnt_rx - 1'b1;
        end
    end
    always @(negedge bit_clk or posedge rst) begin
        if (rst) begin
            rx_data <= 0;
            rx_val <= 0;
        end else begin
            rx_data <= sr_rx;
            rx_val <= (bit_cnt_rx == 4'd9);
        end
    end
`else
    // Simulation: internal loopback (PISO/SIPO model)
    reg [9:0] sr_tx;
    reg [3:0] bit_cnt_tx;
    always @(posedge bit_clk or posedge rst) begin
        if (rst) begin
            sr_tx <= 10'b0;
            bit_cnt_tx <= 0;
        end else if (tx_en) begin
            sr_tx <= tx_data;
            bit_cnt_tx <= 4'd9;
        end else if (|bit_cnt_tx) begin
            sr_tx <= {{sr_tx[8:0], 1'b0}};
            bit_cnt_tx <= bit_cnt_tx - 1'b1;
        end
    end
    assign tx_busy = |bit_cnt_tx;
    assign ser_tx_p = |bit_cnt_tx ? sr_tx[9] : 1'b1;
    assign ser_tx_n = ~ser_tx_p;

    // Receive from serial (loopback through connecting wire in sim_top)
    reg [9:0] sr_rx;
    reg [3:0] bit_cnt_rx;
    always @(posedge bit_clk or posedge rst) begin
        if (rst) begin
            sr_rx <= 10'b0;
            bit_cnt_rx <= 0;
        end else if (bit_cnt_rx == 0) begin
            if (bitslip)
                sr_rx <= {{sr_rx[8:0], ser_rx_p}};
            else
                sr_rx <= {{ser_rx_p, sr_rx[9:1]}};
            bit_cnt_rx <= 4'd9;
        end else begin
            sr_rx <= {{sr_rx[8:0], ser_rx_p}};
            bit_cnt_rx <= bit_cnt_rx - 1'b1;
        end
